const csv = $('Consulta CSV').first().json.data;
const clientes = $('Receber clientes').first().json.body.clientes;

// Transformar o CSV em uma lista de investimentos
const linhas = csv.trim().split(/\r?\n/);

const investimentos = linhas.slice(1).map(linha => {
  const [perfil, produto, minimo, rentabilidade] = linha.split(',');

  return {
    perfil: perfil.trim(),
    produto: produto.trim(),
    minimo: Number(minimo),
    rentabilidade: rentabilidade.trim()
  };
});

// Converter saldo brasileiro para número
function converterSaldo(valor) {
  return Number(
    valor.replace('R$', '').replace(/\./g, '').replace(',', '.').trim()
  );
}

// Cruzar cada cliente com os investimentos compatíveis
return clientes.map(cliente => {
  const saldo = converterSaldo(cliente.saldo);

  const opcoes = investimentos.filter(investimento =>
    investimento.perfil === cliente.perfil &&
    saldo >= investimento.minimo
  );

  return {
    json: {
      ...cliente,
      investimentos: opcoes
    }
  };
});

const clientes = $input.all();

return clientes.map(item => {
  const cliente = item.json;

  const descricoes = {
    Conservador: "priorizar estabilidade e segurança",
    Moderado: "equilibrar segurança e potencial de crescimento",
    Arrojado: "buscar maior potencial de retorno, aceitando mais riscos"
  };

  const produtos = cliente.investimentos
    .map(investimento => investimento.produto)
    .join(", ");

  const mensagem = `Olá, ${cliente.nome}!

Considerando seu perfil ${cliente.perfil} e seu saldo de ${cliente.saldo}, identificamos as seguintes opções para análise:

${produtos || "Nenhuma opção encontrada para seu saldo atual."}

Para seu perfil, o objetivo é ${descricoes[cliente.perfil] || "avaliar alternativas de investimento"}.

Esta é uma simulação educacional, não uma recomendação financeira individualizada.`;

  return {
    json: {
      ...cliente,
      mensagem: mensagem
    }
  };
});
